        &&& self.fc_clients.instance_id() == pre.fc_clients.instance_id()
        &&& self.fc_clients.key() == pre.fc_clients.key()
        &&& self.cell_id == pre.cell_id
        &&& self.batch_perms.is_none()
        &&& self.local_updates.is_none()
    }

